{"command":"mkdir -p /tmp/ptyt && cd /tmp/ptyt && cat > p.c <<'EOF'
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <pty.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/wait.h>
#include <termios.h>
int main(){
  int m, s; char name[64];
  if (openpty(&m, &s, name, NULL, NULL) != 0) { perror("openpty"); return 1; }
  printf("pty %s\n", name); fflush(stdout);
  pid_t p = fork();
  if (p == 0) {
    close(m);
    int fd = open("/dev/tty", O_RDWR|O_NOCTTY);
    if (fd >= 0) { ioctl(fd, TIOCNOTTY, NULL); close(fd); }
    if (setsid() < 0) printf("setsid: %s\n", strerror(errno));
    fd = open("/dev/tty", O_RDWR|O_NOCTTY);
    if (fd >= 0) { printf("Failed to disconnect\n"); close(fd);}
    if (ioctl(s, TIOCSCTTY, 0) < 0) printf("TIOCSCTTY: %s\n", strerror(errno));
    fd = open(name, O_RDWR);
    if (fd < 0) printf("%s: %s\n", name, strerror(errno)); else close(fd);
    fd = open("/dev/tty", O_WRONLY);
    if (fd < 0) printf("devtty: %s\n", strerror(errno)); else close(fd);
    printf("child done\n");
    _exit(0);
  }
  waitpid(p, NULL, 0);
  return 0;
}
EOF
gcc -o p p.c -lutil && ./p; setsid ./p"}

