int bn_is_prime(const bn *a, int rounds) {
    if (a->n == 0) return 0;
    if (a->n == 1 && a->d[0] < 2) return 0;
    if (!bn_is_odd(a)) return a->n == 1 && a->d[0] == 2;
    for (size_t i = 0; i < sizeof(small_primes)/sizeof(small_primes[0]); i++) {
