        p->d[(bits-1)/32] |= 1u << ((bits-1) % 32);
        if (p->n < (bits + 31) / 32) p->n = (bits + 31) / 32;
        int b2 = bits - 2;
        p->d[b2/32] |= 1u << (b2 % 32);
        p->d[0] |= 1;
        if (bn_is_prime(p, 20)) return;
    }
}
