#define MM(r,a,b) bn_mont_mul(&c->pm, r, a, b)
#define MADD(r,a,b) bn_modadd(r, a, b, &c->p)
#define MSUB(r,a,b) bn_modsub(r, a, b, &c->p)

static void pt_double(const ecc_curve *c, ecc_point *r, const ecc_point *p) {
    if (p->inf || bn_is_zero(&p->y)) { r->inf = 1; return; }
    bn delta, gamma, beta, alpha, t1, t2, x3, y3, z3;
    MM(&delta, &p->z, &p->z);
    MM(&gamma, &p->y, &p->y);
    MM(&beta, &p->x, &gamma);
    MSUB(&t1, &p->x, &delta);
    MADD(&t2, &p->x, &delta);
    MM(&alpha, &t1, &t2);
    MADD(&t1, &alpha, &alpha); MADD(&alpha, &t1, &alpha); /* alpha = 3*(x-d)(x+d) */
    MM(&x3, &alpha, &alpha);
    MADD(&t1, &beta, &beta); MADD(&t1, &t1, &t1); MADD(&t2, &t1, &t1); /* t1=4beta, t2=8beta */
    MSUB(&x3, &x3, &t2);
    MADD(&t2, &p->y, &p->z);
    MM(&z3, &t2, &t2);
    MSUB(&z3, &z3, &gamma);
    MSUB(&z3, &z3, &delta);
    MSUB(&t1, &t1, &x3);
    MM(&y3, &alpha, &t1);
    MM(&t2, &gamma, &gamma);
    MADD(&t2, &t2, &t2); MADD(&t2, &t2, &t2); MADD(&t2, &t2, &t2);
    MSUB(&y3, &y3, &t2);
    bn_copy(&r->x, &x3); bn_copy(&r->y, &y3); bn_copy(&r->z, &z3); r->inf = 0;
}

static void pt_add(const ecc_curve *c, ecc_point *r, const ecc_point *p, const ecc_point *q) {
    if (p->inf) { *r = *q; return; }
    if (q->inf) { *r = *p; return; }
    bn z1z1, z2z2, u1, u2, s1, s2, h, rr, t, hh, hhh, v, x3, y3, z3;
    MM(&z1z1, &p->z, &p->z);
    MM(&z2z2, &q->z, &q->z);
    MM(&u1, &p->x, &z2z2);
    MM(&u2, &q->x, &z1z1);
    MM(&t, &q->z, &z2z2); MM(&s1, &p->y, &t);
    MM(&t, &p->z, &z1z1); MM(&s2, &q->y, &t);
    if (bn_cmp(&u1, &u2) == 0) {
        if (bn_cmp(&s1, &s2) == 0) { pt_double(c, r, p); return; }
        r->inf = 1; return;
    }
    MSUB(&h, &u2, &u1);
    MSUB(&rr, &s2, &s1);
    MM(&hh, &h, &h);
    MM(&hhh, &h, &hh);
    MM(&v, &u1, &hh);
    MM(&x3, &rr, &rr);
    MSUB(&x3, &x3, &hhh);
    MSUB(&x3, &x3, &v);
    MSUB(&x3, &x3, &v);
    MSUB(&t, &v, &x3);
    MM(&y3, &rr, &t);
    MM(&t, &s1, &hhh);
    MSUB(&y3, &y3, &t);
    MM(&t, &p->z, &q->z);
    MM(&z3, &t, &h);
    bn_copy(&r->x, &x3); bn_copy(&r->y, &y3); bn_copy(&r->z, &z3); r->inf = 0;
}

static void mont_inv(const ecc_curve *c, bn *r, const bn *a) {
    /* a in mont form: compute a^(p-2) in mont domain */
    bn e; bn_sub_u32(&e, &c->p, 2);
    bn res; bn_copy(&res, &c->pm.one);
    for (int i = bn_bits(&e) - 1; i >= 0; i--) {
        MM(&res, &res, &res);
        if (bn_bit(&e, i)) MM(&res, &res, a);
    }
    bn_copy(r, &res);
}

int ecc_on_curve(const ecc_curve *c, const bn *x, const bn *y) {
    if (bn_cmp(x, &c->p) >= 0 || bn_cmp(y, &c->p) >= 0) return 0;
    bn xm, ym, l, r, t;
    bn_to_mont(&c->pm, &xm, x); bn_to_mont(&c->pm, &ym, y);
    MM(&l, &ym, &ym);
    MM(&t, &xm, &xm); MM(&r, &t, &xm);
    MM(&t, &c->am, &xm); MADD(&r, &r, &t);
    MADD(&r, &r, &c->bm);
    return bn_cmp(&l, &r) == 0;
}

int ecc_mul(const ecc_curve *c, const bn *k, const bn *x, const bn *y, bn *rx, bn *ry) {
    ecc_point P, R;
    bn_to_mont(&c->pm, &P.x, x); bn_to_mont(&c->pm, &P.y, y); bn_copy(&P.z, &c->pm.one); P.inf = 0;
    R.inf = 1;
    for (int i = bn_bits(k) - 1; i >= 0; i--) {
        pt_double(c, &R, &R);
        if (bn_bit(k, i)) pt_add(c, &R, &R, &P);
    }
    if (R.inf) return 0;
    bn zi, zi2, zi3, t;
    mont_inv(c, &zi, &R.z);
    MM(&zi2, &zi, &zi); MM(&zi3, &zi2, &zi);
    MM(&t, &R.x, &zi2); bn_from_mont(&c->pm, rx, &t);
    MM(&t, &R.y, &zi3); bn_from_mont(&c->pm, ry, &t);
    return 1;
}
int ecc_mul_g(const ecc_curve *c, const bn *k, bn *rx, bn *ry) { return ecc_mul(c, k, &c->gx, &c->gy, rx, ry); }

/* r = u1*G + u2*Q */
static int ecc_mul2(const ecc_curve *c, const bn *u1, const bn *u2, const bn *qx, const bn *qy, bn *rx) {
    ecc_point G, Q, GQ, R;
    bn_to_mont(&c->pm, &G.x, &c->gx); bn_to_mont(&c->pm, &G.y, &c->gy); bn_copy(&G.z, &c->pm.one); G.inf = 0;
    bn_to_mont(&c->pm, &Q.x, qx); bn_to_mont(&c->pm, &Q.y, qy); bn_copy(&Q.z, &c->pm.one); Q.inf = 0;
    pt_add(c, &GQ, &G, &Q);
    R.inf = 1;
    int bits = bn_bits(u1) > bn_bits(u2) ? bn_bits(u1) : bn_bits(u2);
    for (int i = bits - 1; i >= 0; i--) {
        pt_double(c, &R, &R);
        int b1 = bn_bit(u1, i), b2 = bn_bit(u2, i);
        if (b1 && b2) pt_add(c, &R, &R, &GQ);
        else if (b1) pt_add(c, &R, &R, &G);
        else if (b2) pt_add(c, &R, &R, &Q);
    }
    if (R.inf) return 0;
    bn zi, zi2, t;
    mont_inv(c, &zi, &R.z);
    MM(&zi2, &zi, &zi);
    MM(&t, &R.x, &zi2); bn_from_mont(&c->pm, rx, &t);
    return 1;
}

int ecc_decode_point(const ecc_curve *c, const uint8_t *buf, size_t len, bn *x, bn *y) {
    if (len != (size_t)(1 + 2 * c->size) || buf[0] != 4) return 0;
    bn_from_bytes(x, buf + 1, c->size);
    bn_from_bytes(y, buf + 1 + c->size, c->size);
    return ecc_on_curve(c, x, y);
}
void ecc_encode_point(const ecc_curve *c, const bn *x, const bn *y, uint8_t *out) {
    out[0] = 4;
    bn_to_bytes(x, out + 1, c->size);
    bn_to_bytes(y, out + 1 + c->size, c->size);
}

static void hash_to_bn(const ecc_curve *c, const uint8_t *hash, int hlen, bn *z) {
    bn_from_bytes(z, hash, hlen);
    int nbits = bn_bits(&c->n);
    if (hlen * 8 > nbits) bn_shr(z, z, hlen * 8 - nbits);
}

void ecdsa_sign(const ecc_curve *c, const bn *d, const uint8_t *hash, int hlen, bn *r, bn *s) {
    bn z, k, kx, ky, kinv, t, one;
    hash_to_bn(c, hash, hlen, &z);
    bn_set_u32(&one, 1);
    for (;;) {
        bn_rand_range(&k, &one, &c->n);
        if (!ecc_mul_g(c, &k, &kx, &ky)) continue;
        bn_mod(r, &kx, &c->n);
        if (bn_is_zero(r)) continue;
        bn_modinv(&kinv, &k, &c->n);
        bn_modmul(&t, r, d, &c->n);
        bn zz; bn_mod(&zz, &z, &c->n);
        bn_modadd(&t, &t, &zz, &c->n);
        bn_modmul(s, &kinv, &t, &c->n);
        if (bn_is_zero(s)) continue;
        return;
    }
}

int ecdsa_verify(const ecc_curve *c, const bn *qx, const bn *qy, const uint8_t *hash, int hlen, const bn *r, const bn *s) {
    bn z, w, u1, u2, x;
    if (bn_is_zero(r) || bn_is_zero(s) || bn_cmp(r, &c->n) >= 0 || bn_cmp(s, &c->n) >= 0) return 0;
    hash_to_bn(c, hash, hlen, &z);
    bn_mod(&z, &z, &c->n);
    if (!bn_modinv(&w, s, &c->n)) return 0;
    bn_modmul(&u1, &z, &w, &c->n);
    bn_modmul(&u2, r, &w, &c->n);
    if (!ecc_mul2(c, &u1, &u2, qx, qy, &x)) return 0;
    bn_mod(&x, &x, &c->n);
    return bn_cmp(&x, r) == 0;
}

void ecc_genkey(const ecc_curve *c, bn *d, bn *qx, bn *qy) {
    bn one; bn_set_u32(&one, 1);
    do { bn_rand_range(d, &one, &c->n); } while (!ecc_mul_g(c, d, qx, qy));
}
