    MSUB(&x3, &x3, &t2);
    MADD(&t2, &p->y, &p->z);
    MM(&z3, &t2, &t2);
    MSUB(&z3, &z3, &gamma);
    MSUB(&z3, &z3, &delta);
    MSUB(&t1, &t1, &x3);
    MM(&y3, &alpha, &t1);
    MM(&t2, &gamma, &gamma);
    MADD(&t2, &t2, &t2); MADD(&t2, &t2, &t2); MADD(&t2, &t2, &t2);
    MSUB(&y3, &y3, &t2);
    bn_copy(&r->x, &x3); bn_copy(&r->y, &y3); bn_copy(&r->z, &z3); r->inf = 0;
}

static void pt_add(const ecc_curve *c, ecc_point *r, const ecc_point *p, const ecc_point *q) {
    if (p->inf) { *r = *q; return; }
