    MM(&t, &p->z, &z1z1); MM(&s2, &q->y, &t);
    if (bn_cmp(&u1, &u2) == 0) {
        if (bn_cmp(&s1, &s2) == 0) { pt_double(c, r, p); return; }
        r->inf = 1; return;
    }
    MSUB(&h, &u2, &u1);
    MSUB(&rr, &s2, &s1);
    MM(&hh, &h, &h);
    MM(&hhh, &h, &hh);
    MM(&v, &u1, &hh);
    MM(&x3, &rr, &rr);
    MSUB(&x3, &x3, &hhh);
