static void mont_inv(const ecc_curve *c, bn *r, const bn *a) {
    /* a in mont form: compute a^(p-2) in mont domain */
    bn e; bn_sub_u32(&e, &c->p, 2);
    bn res; bn_copy(&res, &c->pm.one);
    for (int i = bn_bits(&e) - 1; i >= 0; i--) {
        MM(&res, &res, &res);
        if (bn_bit(&e, i)) MM(&res, &res, a);
    }
    bn_copy(r, &res);
}

int ecc_on_curve(const ecc_curve *c, const bn *x, const bn *y) {
    if (bn_cmp(x, &c->p) >= 0 || bn_cmp(y, &c->p) >= 0) return 0;
    bn xm, ym, l, r, t;
    bn_to_mont(&c->pm, &xm, x); bn_to_mont(&c->pm, &ym, y);
    MM(&l, &ym, &ym);
    MM(&t, &xm, &xm); MM(&r, &t, &xm);
    MM(&t, &c->am, &xm); MADD(&r, &r, &t);
    MADD(&r, &r, &c->bm);
    return bn_cmp(&l, &r) == 0;
}

int ecc_mul(const ecc_curve *c, const bn *k, const bn *x, const bn *y, bn *rx, bn *ry) {
    ecc_point P, R;
    bn_to_mont(&c->pm, &P.x, x); bn_to_mont(&c->pm, &P.y, y); bn_copy(&P.z, &c->pm.one); P.inf = 0;
    R.inf = 1;
    for (int i = bn_bits(k) - 1; i >= 0; i--) {
        pt_double(c, &R, &R);
        if (bn_bit(k, i)) pt_add(c, &R, &R, &P);
    }
    if (R.inf) return 0;
    bn zi, zi2, zi3, t;
    mont_inv(c, &zi, &R.z);
    MM(&zi2, &zi, &zi); MM(&zi3, &zi2, &zi);
    MM(&t, &R.x, &zi2); bn_from_mont(&c->pm, rx, &t);
    MM(&t, &R.y, &zi3); bn_from_mont(&c->pm, ry, &t);
    return 1;
}
