/* r = u1*G + u2*Q */
static int ecc_mul2(const ecc_curve *c, const bn *u1, const bn *u2, const bn *qx, const bn *qy, bn *rx) {
    ecc_point G, Q, GQ, R;
    bn_to_mont(&c->pm, &G.x, &c->gx); bn_to_mont(&c->pm, &G.y, &c->gy); bn_copy(&G.z, &c->pm.one); G.inf = 0;
    bn_to_mont(&c->pm, &Q.x, qx); bn_to_mont(&c->pm, &Q.y, qy); bn_copy(&Q.z, &c->pm.one); Q.inf = 0;
    pt_add(c, &GQ, &G, &Q);
    R.inf = 1;
    int bits = bn_bits(u1) > bn_bits(u2) ? bn_bits(u1) : bn_bits(u2);
    for (int i = bits - 1; i >= 0; i--) {
        pt_double(c, &R, &R);
        int b1 = bn_bit(u1, i), b2 = bn_bit(u2, i);
        if (b1 && b2) pt_add(c, &R, &R, &GQ);
        else if (b1) pt_add(c, &R, &R, &G);
        else if (b2) pt_add(c, &R, &R, &Q);
    }
    if (R.inf) return 0;
    bn zi, zi2, t;
    mont_inv(c, &zi, &R.z);
    MM(&zi2, &zi, &zi);
    MM(&t, &R.x, &zi2); bn_from_mont(&c->pm, rx, &t);
    return 1;
}

int ecc_decode_point(const ecc_curve *c, const uint8_t *buf, size_t len, bn *x, bn *y) {
    if (len != (size_t)(1 + 2 * c->size) || buf[0] != 4) return 0;
    bn_from_bytes(x, buf + 1, c->size);
    bn_from_bytes(y, buf + 1 + c->size, c->size);
    return ecc_on_curve(c, x, y);
}
void ecc_encode_point(const ecc_curve *c, const bn *x, const bn *y, uint8_t *out) {
    out[0] = 4;
    bn_to_bytes(x, out + 1, c->size);
    bn_to_bytes(y, out + 1 + c->size, c->size);
}

static void hash_to_bn(const ecc_curve *c, const uint8_t *hash, int hlen, bn *z) {
    bn_from_bytes(z, hash, hlen);
    int nbits = bn_bits(&c->n);
    if (hlen * 8 > nbits) bn_shr(z, z, hlen * 8 - nbits);
}

void ecdsa_sign(const ecc_curve *c, const bn *d, const uint8_t *hash, int hlen, bn *r, bn *s) {
    bn z, k, kx, ky, kinv, t, one;
    hash_to_bn(c, hash, hlen, &z);
    bn_set_u32(&one, 1);
    for (;;) {
        bn_rand_range(&k, &one, &c->n);
        if (!ecc_mul_g(c, &k, &kx, &ky)) continue;
        bn_mod(r, &kx, &c->n);
        if (bn_is_zero(r)) continue;
        bn_modinv(&kinv, &k, &c->n);
        bn_modmul(&t, r, d, &c->n);
        bn zz; bn_mod(&zz, &z, &c->n);
        bn_modadd(&t, &t, &zz, &c->n);
        bn_modmul(s, &kinv, &t, &c->n);
        if (bn_is_zero(s)) continue;
        return;
    }
}

int ecdsa_verify(const ecc_curve *c, const bn *qx, const bn *qy, const uint8_t *hash, int hlen, const bn *r, const bn *s) {
    bn z, w, u1, u2, x;
    if (bn_is_zero(r) || bn_is_zero(s) || bn_cmp(r, &c->n) >= 0 || bn_cmp(s, &c->n) >= 0) return 0;
    hash_to_bn(c, hash, hlen, &z);
    bn_mod(&z, &z, &c->n);
    if (!bn_modinv(&w, s, &c->n)) return 0;
    bn_modmul(&u1, &z, &w, &c->n);
    bn_modmul(&u2, r, &w, &c->n);
    if (!ecc_mul2(c, &u1, &u2, qx, qy, &x)) return 0;
    bn_mod(&x, &x, &c->n);
    return bn_cmp(&x, r) == 0;
}

void ecc_genkey(const ecc_curve *c, bn *d, bn *qx, bn *qy) {
    bn one; bn_set_u32(&one, 1);
    do { bn_rand_range(d, &one, &c->n); } while (!ecc_mul_g(c, d, qx, qy));
}
