/* ---- Ed25519 ---- */
typedef struct { fe X, Y, Z, T; } ge;
static fe ed_d, ed_d2, ed_sqrtm1;
static ge ed_B;
static int ed_inited = 0;

static const uint8_t d_bytes[32] = {0xa3,0x78,0x59,0x13,0xca,0x4d,0xeb,0x75,0xab,0xd8,0x41,0x41,0x4d,0x0a,0x70,0x00,0x98,0xe8,0x79,0x77,0x79,0x40,0xc7,0x8c,0x73,0xfe,0x6f,0x2b,0xee,0x6c,0x03,0x52};
