    fe_pow2k(&t, &z2_20_0, 20); fe_mul(&t, &t, &z2_20_0);
    fe_pow2k(&t, &t, 10); fe_mul(&z2_50_0, &t, &z2_10_0);
    fe_pow2k(&t, &z2_50_0, 50); fe_mul(&z2_100_0, &t, &z2_50_0);
    fe_pow2k(&t, &z2_100_0, 100); fe_mul(&t, &t, &z2_100_0);
