        uint64_t bit = (e[pos / 8] >> (pos & 7)) & 1;
        swap ^= bit;
        fe_cswap(&x2, &x3, swap); fe_cswap(&z2, &z3, swap);
        swap = bit;
        fe_add(&a, &x2, &z2); fe_carry(&a);
        fe_sq(&aa, &a);
        fe_sub(&b, &x2, &z2); fe_carry(&b);
        fe_sq(&bb, &b);
        fe_sub(&ee, &aa, &bb); fe_carry(&ee);
        fe_add(&c, &x3, &z3); fe_carry(&c);
        fe_sub(&d, &x3, &z3); fe_carry(&d);
        fe_mul(&da, &d, &a);
        fe_mul(&cb, &c, &b);
        fe_add(&t, &da, &cb); fe_carry(&t); fe_sq(&x3, &t);
        fe_sub(&t, &da, &cb); fe_carry(&t); fe_sq(&t, &t); fe_mul(&z3, &x1, &t);
        fe_mul(&x2, &aa, &bb);
        fe_mul_small(&t, &ee, 121665); fe_add(&t, &aa, &t); fe_carry(&t); fe_mul(&z2, &ee, &t);
    }
    fe_cswap(&x2, &x3, swap); fe_cswap(&z2, &z3, swap);
    fe_inv(&z2, &z2);
    fe_mul(&x2, &x2, &z2);
    fe_tobytes(out, &x2);
}
void x25519_base(uint8_t out[32], const uint8_t scalar[32]) {
