/* ---- Ed25519 ---- */
typedef struct { fe X, Y, Z, T; } ge;
static fe ed_d, ed_d2, ed_sqrtm1;
static ge ed_B;
static int ed_inited = 0;

static const uint8_t d_bytes[32] = {0xa3,0x78,0x59,0x13,0xca,0x4d,0xeb,0x75,0xab,0xd8,0x41,0x41,0x4d,0x0a,0x70,0x00,0x98,0xe8,0x79,0x77,0x79,0x40,0xc7,0x8c,0x73,0xfe,0x6f,0x2b,0xee,0x6c,0x03,0x52};
static const uint8_t sqrtm1_bytes[32] = {0xb0,0xa0,0x0e,0x4a,0x27,0x1b,0xee,0xc4,0x78,0xe4,0x2f,0xad,0x06,0x18,0x43,0x2f,0xa7,0xd7,0xfb,0x3d,0x99,0x00,0x4d,0x2b,0x0b,0xdf,0xc1,0x4f,0x80,0x24,0x83,0x2b};
static const uint8_t B_bytes[32] = {0x58,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x66};

static int ge_frombytes(ge *p, const uint8_t s[32]);
static void ed_init(void) {
    if (ed_inited) return;
    fe_frombytes(&ed_d, d_bytes);
    fe_add(&ed_d2, &ed_d, &ed_d); fe_carry(&ed_d2);
    fe_frombytes(&ed_sqrtm1, sqrtm1_bytes);
    ed_inited = 1;
    ge_frombytes(&ed_B, B_bytes);
}

static void ge_zero(ge *p) { fe_0(&p->X); fe_1(&p->Y); fe_1(&p->Z); fe_0(&p->T); }

static void ge_add(ge *r, const ge *p, const ge *q) {
    fe a, b, c, d, e, f, g, h, t;
    fe_sub(&t, &p->Y, &p->X); fe_carry(&t);
    fe_sub(&a, &q->Y, &q->X); fe_carry(&a); fe_mul(&a, &t, &a);
    fe_add(&t, &p->Y, &p->X); fe_carry(&t);
    fe_add(&b, &q->Y, &q->X); fe_carry(&b); fe_mul(&b, &t, &b);
    fe_mul(&c, &p->T, &q->T); fe_mul(&c, &c, &ed_d2);
    fe_mul(&d, &p->Z, &q->Z); fe_add(&d, &d, &d); fe_carry(&d);
    fe_sub(&e, &b, &a); fe_carry(&e);
    fe_sub(&f, &d, &c); fe_carry(&f);
    fe_add(&g, &d, &c); fe_carry(&g);
    fe_add(&h, &b, &a); fe_carry(&h);
    fe_mul(&r->X, &e, &f);
    fe_mul(&r->Y, &g, &h);
    fe_mul(&r->T, &e, &h);
    fe_mul(&r->Z, &f, &g);
}
static void ge_double(ge *r, const ge *p) { ge_add(r, p, p); }

static void ge_scalarmult(ge *r, const uint8_t k[32], const ge *p) {
    ge acc; ge_zero(&acc);
    for (int i = 255; i >= 0; i--) {
        ge_double(&acc, &acc);
