    fe_sub(&check, &vxx, &u); fe_carry(&check);
    if (fe_isnonzero(&check)) {
        fe_add(&check, &vxx, &u); fe_carry(&check);
        if (fe_isnonzero(&check)) return 0;
        fe_mul(&x, &x, &ed_sqrtm1);
    }
    if (fe_isneg(&x) != (s[31] >> 7)) {
        if (!fe_isnonzero(&x)) return 0;
        fe_neg(&x, &x);
    }
    p->X = x; p->Y = y; fe_1(&p->Z); fe_mul(&p->T, &x, &y);
