#include "buf.h"
#include "util.h"
#include <stdlib.h>
#include <string.h>

buffer *buf_new(unsigned int size) {
    if (size > BUF_MAX_SIZE) fatal_exit("buf->size too big");
    buffer *b = m_malloc(sizeof(buffer));
    b->data = size ? m_malloc(size) : NULL;
    b->size = size; b->len = 0; b->pos = 0;
    return b;
}
void buf_free(buffer *b) { if (b) { free(b->data); free(b); } }
void buf_burn_free(buffer *b) { if (b) { if (b->data) m_burn(b->data, b->size); buf_free(b); } }
buffer *buf_resize(buffer *b, unsigned int newsize) {
    if (newsize > BUF_MAX_SIZE) fatal_exit("buf->size too big");
    b->data = m_realloc(b->data, newsize ? newsize : 1);
    b->size = newsize;
    if (b->len > newsize) b->len = newsize;
    if (b->pos > b->len) b->pos = b->len;
    return b;
}
buffer *buf_newcopy(const buffer *b) {
    buffer *r = buf_new(b->len);
    r->len = b->len;
    if (b->len) memcpy(r->data, b->data, b->len);
    return r;
}
void buf_setlen(buffer *b, unsigned int len) { if (len > b->size) fatal_exit("Bad buf_setlen"); b->len = len; if (b->pos > len) b->pos = len; }
void buf_incrlen(buffer *b, unsigned int incr) { if (incr > BUF_MAX_SIZE || (b->len + incr) > b->size) fatal_exit("Bad buf_incrlen"); b->len += incr; }
void buf_setpos(buffer *b, unsigned int pos) { if (pos > b->len) fatal_exit("Bad buf_setpos"); b->pos = pos; }
void buf_incrwritepos(buffer *b, unsigned int incr) {
    if (incr > BUF_MAX_SIZE || (b->pos + incr) > b->size) fatal_exit("Bad buf_incrwritepos");
    b->pos += incr;
    if (b->pos > b->len) b->len = b->pos;
}
void buf_incrpos(buffer *b, unsigned int incr) {
    if (incr > BUF_MAX_SIZE || (b->pos + incr) > b->len) fatal_exit("Bad buf_incrpos");
    b->pos += incr;
}
void buf_decrpos(buffer *b, unsigned int decr) { if (decr > b->pos) fatal_exit("Bad buf_decrpos"); b->pos -= decr; }
uint8_t buf_getbyte(buffer *b) {
    if (b->pos >= b->len) fatal_exit("Bad buf_getbyte");
    return b->data[b->pos++];
}
uint8_t buf_getbool(buffer *b) { uint8_t v = buf_getbyte(b); if (v != 0) v = 1; return v; }
static void buf_ensure(buffer *b, unsigned int extra) {
    if (b->pos + extra > b->size) {
        unsigned int ns = b->size * 2 + extra + 64;
        buf_resize(b, ns);
    }
}
void buf_putbyte(buffer *b, uint8_t v) {
    buf_ensure(b, 1);
    b->data[b->pos++] = v;
    if (b->pos > b->len) b->len = b->pos;
}
uint8_t *buf_getptr(const buffer *b, unsigned int len) {
    if (len > BUF_MAX_SIZE || b->pos + len > b->len) fatal_exit("Bad buf_getptr");
    return b->data + b->pos;
}
uint8_t *buf_getwriteptr(const buffer *b, unsigned int len) {
    if (len > BUF_MAX_SIZE || b->pos + len > b->size) fatal_exit("Bad buf_getwriteptr");
    return b->data + b->pos;
}
uint32_t buf_getint(buffer *b) {
    uint8_t *p = buf_getptr(b, 4);
    uint32_t v = ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
    buf_incrpos(b, 4);
    return v;
}
char *buf_getstring(buffer *b, unsigned int *retlen) {
    unsigned int len = buf_getint(b);
    if (len > MAX_STRING_LEN) fatal_exit("String too long");
    if (retlen) *retlen = len;
    char *ret = m_malloc(len + 1);
    memcpy(ret, buf_getptr(b, len), len);
    buf_incrpos(b, len);
    ret[len] = '\0';
    return ret;
}
buffer *buf_getbuf(buffer *b, unsigned int len) {
    buffer *r = buf_new(len);
    memcpy(r->data, buf_getptr(b, len), len);
    buf_incrpos(b, len);
    r->len = len;
    return r;
}
buffer *buf_getstringbuf(buffer *b) {
    unsigned int len = buf_getint(b);
    if (len > MAX_STRING_LEN) fatal_exit("String too long");
    return buf_getbuf(b, len);
}
void buf_eatstring(buffer *b) { unsigned int len = buf_getint(b); buf_incrpos(b, len); }
void buf_putint(buffer *b, uint32_t v) {
    buf_ensure(b, 4);
    uint8_t *p = b->data + b->pos;
    p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = v;
    b->pos += 4; if (b->pos > b->len) b->len = b->pos;
}
void buf_putbytes(buffer *b, const void *bytes, unsigned int len) {
    buf_ensure(b, len);
    if (len) memcpy(b->data + b->pos, bytes, len);
    b->pos += len; if (b->pos > b->len) b->len = b->pos;
}
void buf_putstring(buffer *b, const void *str, unsigned int len) { buf_putint(b, len); buf_putbytes(b, str, len); }
