enum keytype {
    KEY_NONE = 0,
    KEY_RSA,
    KEY_ECDSA256,
    KEY_ECDSA384,
    KEY_ECDSA521,
    KEY_ED25519,
    KEY_SK_ECDSA256,
    KEY_SK_ED25519,
    KEY_UNKNOWN
};

enum sigtype {
    SIG_NONE = 0,
    SIG_RSA_SHA256,
    SIG_ECDSA256,
    SIG_ECDSA384,
    SIG_ECDSA521,
    SIG_ED25519,
    SIG_SK_ECDSA256,
    SIG_SK_ED25519,
    SIG_UNKNOWN
};

typedef struct {
    enum keytype type;
    /* rsa */
    bn *e, *n, *d, *p, *q;
    /* ecdsa */
    const ecc_curve *curve;
    bn *ecd, *qx, *qy;
    int has_priv;
    /* ed25519 */
    uint8_t edpriv[32], edpub[32];
