sign_key *key_new(void);
void key_free(sign_key *k);
/* parse private key (dropbear format). returns 1 success, 0 failure. may fatal on malformed buffers */
int buf_get_priv_key(buffer *b, sign_key *k, enum keytype *type);
int buf_get_pub_key(buffer *b, sign_key *k, enum keytype *type);
void buf_put_pub_key(buffer *b, const sign_key *k);
