#include "signkey.h"
#include "util.h"
#include "sha2.h"
#include "c25519.h"
#include <string.h>
#include <stdlib.h>

static const char *keynames[] = {
    [KEY_RSA] = "ssh-rsa",
    [KEY_ECDSA256] = "ecdsa-sha2-nistp256",
    [KEY_ECDSA384] = "ecdsa-sha2-nistp384",
    [KEY_ECDSA521] = "ecdsa-sha2-nistp521",
    [KEY_ED25519] = "ssh-ed25519",
    [KEY_SK_ECDSA256] = "sk-ecdsa-sha2-nistp256@openssh.com",
    [KEY_SK_ED25519] = "sk-ssh-ed25519@openssh.com",
};
static const char *signames[] = {
    [SIG_RSA_SHA256] = "rsa-sha2-256",
    [SIG_ECDSA256] = "ecdsa-sha2-nistp256",
    [SIG_ECDSA384] = "ecdsa-sha2-nistp384",
    [SIG_ECDSA521] = "ecdsa-sha2-nistp521",
    [SIG_ED25519] = "ssh-ed25519",
    [SIG_SK_ECDSA256] = "sk-ecdsa-sha2-nistp256@openssh.com",
    [SIG_SK_ED25519] = "sk-ssh-ed25519@openssh.com",
};

const char *keytype_name(enum keytype t) { if (t > KEY_NONE && t < KEY_UNKNOWN) return keynames[t]; return "unknown"; }
enum keytype keytype_from_name(const char *name, unsigned int len) {
    for (int i = KEY_RSA; i < KEY_UNKNOWN; i++) if (buf_strmatch(name, len, keynames[i])) return (enum keytype)i;
    return KEY_UNKNOWN;
}
const char *sigtype_name(enum sigtype t) { if (t > SIG_NONE && t < SIG_UNKNOWN) return signames[t]; return "unknown"; }
enum sigtype sigtype_from_name(const char *name, unsigned int len) {
    for (int i = SIG_RSA_SHA256; i < SIG_UNKNOWN; i++) if (buf_strmatch(name, len, signames[i])) return (enum sigtype)i;
    return SIG_UNKNOWN;
}
enum keytype keytype_for_sig(enum sigtype s) {
    switch (s) {
        case SIG_RSA_SHA256: return KEY_RSA;
        case SIG_ECDSA256: return KEY_ECDSA256;
        case SIG_ECDSA384: return KEY_ECDSA384;
        case SIG_ECDSA521: return KEY_ECDSA521;
        case SIG_ED25519: return KEY_ED25519;
        case SIG_SK_ECDSA256: return KEY_SK_ECDSA256;
        case SIG_SK_ED25519: return KEY_SK_ED25519;
        default: return KEY_UNKNOWN;
    }
}
enum sigtype sigtype_for_key(enum keytype t) {
    switch (t) {
        case KEY_RSA: return SIG_RSA_SHA256;
        case KEY_ECDSA256: return SIG_ECDSA256;
        case KEY_ECDSA384: return SIG_ECDSA384;
        case KEY_ECDSA521: return SIG_ECDSA521;
        case KEY_ED25519: return SIG_ED25519;
        case KEY_SK_ECDSA256: return SIG_SK_ECDSA256;
        case KEY_SK_ED25519: return SIG_SK_ED25519;
        default: return SIG_UNKNOWN;
    }
}

static bn *bn_new(void) { bn *b = m_malloc(sizeof(bn)); bn_zero(b); return b; }
sign_key *key_new(void) { return m_malloc(sizeof(sign_key)); }
void key_free(sign_key *k) {
    if (!k) return;
    free(k->e); free(k->n); free(k->d); free(k->p); free(k->q);
    free(k->ecd); free(k->qx); free(k->qy); free(k->sk_app);
    m_burn(k, sizeof(*k));
    free(k);
}

static int get_rsa_pub(buffer *b, sign_key *k) {
    buf_incrpos(b, buf_getint(b)); /* skip name */
    k->e = bn_new(); k->n = bn_new();
    if (!buf_getmpint(b, k->e)) return 0;
    if (!buf_getmpint(b, k->n)) return 0;
    if (bn_bits(k->n) < 1024) { dlog("RSA key too short"); return 0; }
    if (bn_bits(k->e) > 64) { dlog("RSA key bad e"); return 0; }
    return 1;
}
static int get_rsa_priv(buffer *b, sign_key *k) {
    if (!get_rsa_pub(b, k)) return 0;
    k->d = bn_new();
    if (!buf_getmpint(b, k->d)) return 0;
    if (b->pos == b->len) return 1;
    k->p = bn_new(); k->q = bn_new();
    if (!buf_getmpint(b, k->p)) return 0;
    if (!buf_getmpint(b, k->q)) return 0;
    return 1;
}

static int get_ecdsa_pub(buffer *b, sign_key *k, int sk) {
    unsigned int idlen, curvelen;
    char *ident = buf_getstring(b, &idlen);
    char *curve = buf_getstring(b, &curvelen);
    int ret = 0;
    if (sk) {
        if (strcmp(curve, "nistp256") != 0) goto out;
    } else {
        if (idlen != curvelen + strlen("ecdsa-sha2-")) goto out;
        if (memcmp(ident + strlen("ecdsa-sha2-"), curve, curvelen) != 0) goto out;
    }
    const ecc_curve *c = NULL;
    static const int bits[3] = {256, 384, 521};
    for (int i = 0; i < 3; i++) {
        const ecc_curve *cc = ecc_get_curve(bits[i]);
        if (memcmp(curve, cc->name, strlen(cc->name)) == 0) { c = cc; break; }
    }
    if (!c) goto out;
    buffer *q = buf_getstringbuf(b);
    k->qx = bn_new(); k->qy = bn_new();
    if (!ecc_decode_point(c, q->data, q->len, k->qx, k->qy)) { buf_free(q); goto out; }
    buf_free(q);
    k->curve = c;
    ret = 1;
out:
    free(ident); free(curve);
    return ret;
}

static int get_ed25519_pub(buffer *b, sign_key *k) {
    buf_incrpos(b, buf_getint(b));
    unsigned int len = buf_getint(b);
    if (len != 32 || b->len - b->pos < len) return 0;
    memcpy(k->edpub, buf_getptr(b, 32), 32);
